export type CatalogPlatform = CatalogModel['platform']

export const catalogModelsForPlatform = (platform: string): string[] =>
  modelCatalog.filter((model) => model.platform === platform).map((model) => model.id)

export const catalogPresetMappingsForPlatform = (platform: string) =>
  modelCatalog
    .filter((model) => model.platform === platform)
    .map((model) => ({
      label: model.displayName,
      from: model.preset.from,
      to: model.preset.to,
      color: model.preset.color
    }))

export const optionalCatalogClientDefaultForPlatform = (platform: string) =>
  modelCatalog.find((candidate) => candidate.platform === platform && candidate.clientDefault)

export const catalogClientDefaultForPlatform = (platform: string) => {
  const model = optionalCatalogClientDefaultForPlatform(platform)
  if (!model) throw new Error(`missing catalog client default for ${platform}`)
  return model
}
